operations.text:
query TestNode(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Character {
      id
      name
    }
    ... on Episode {
      id
      name
    }
    id
  }
}

mutation TestRename(
  $id: ID!
  $name: String!
) {
  rename(id: $id, name: $name) {
    character {
      id
      name
    }
  }
}

mutation TestRenameThroughFragment(
  $id: ID!
  $name: String!
) {
  ...TestRenamePayload_mutation
}

fragment TestRenamePayload_mutation on Mutation {
  rename(id: $id, name: $name) {
    character {
      id
      name
    }
  }
}

mutation TestRenameWithOrigin(
  $id: ID!
  $name: String!
  $withOrigin: Boolean!
) {
  rename(id: $id, name: $name) {
    character {
      id
      name
      origin @include(if: $withOrigin) {
        id
        name
      }
    }
  }
}

query TestSearch(
  $name: String!
) {
  search(name: $name) {
    __typename
    ... on Character {
      id
      name
    }
    ... on Location {
      id
      name
      dimension
    }
    ... on Node {
      __isNode: __typename
      id
    }
  }
}

query TestSearchOrigins(
  $name: String!
) {
  search(name: $name) {
    __typename
    ... on Character {
      origin {
        name
        id
      }
    }
    ... on Node {
      __isNode: __typename
      id
    }
  }
}

mutation TestSetFavorite(
  $id: ID!
  $favorite: Boolean!
) {
  setFavorite(id: $id, favorite: $favorite) {
    character {
      id
      name
      favorite
    }
  }
}
